#include <stdio.h>
#include <stdlib.h>

static int find_root(int *parent, int x) {
    int root = x;
    while (parent[root] != root) {
        root = parent[root];
    }
    while (parent[x] != x) {
        int next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) {
        return 0;
    }

    int *parent = malloc((size_t)n * sizeof(int));
    int *size = calloc((size_t)n, sizeof(int));
    int *degree = calloc((size_t)n, sizeof(int));
    int *head = malloc((size_t)n * sizeof(int));
    int *to = malloc((size_t)(2 * m) * sizeof(int));
    int *next = malloc((size_t)(2 * m) * sizeof(int));
    int *member_head = malloc((size_t)n * sizeof(int));
    int *member_next = malloc((size_t)n * sizeof(int));
    int *marked = calloc((size_t)n, sizeof(int));

    for (int i = 0; i < n; i++) {
        parent[i] = i;
        head[i] = -1;
        member_head[i] = -1;
    }

    int edge_count = 0;
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u;
        --v;

        to[edge_count] = v;
        next[edge_count] = head[u];
        head[u] = edge_count++;
        to[edge_count] = u;
        next[edge_count] = head[v];
        head[v] = edge_count++;

        degree[u]++;
        degree[v]++;

        int ru = find_root(parent, u);
        int rv = find_root(parent, v);
        if (ru != rv) {
            parent[rv] = ru;
        }
    }

    for (int i = 0; i < n; i++) {
        int root = find_root(parent, i);
        size[root]++;
        member_next[i] = member_head[root];
        member_head[root] = i;
    }

    for (int root = 0; root < n; root++) {
        if (size[root] < 3) {
            continue;
        }

        int candidate = -1;
        for (int v = member_head[root]; v != -1; v = member_next[v]) {
            if (degree[v] < size[root] - 1) {
                candidate = v;
                break;
            }
        }
        if (candidate == -1) {
            continue;
        }

        for (int e = head[candidate]; e != -1; e = next[e]) {
            marked[to[e]] = 1;
        }

        for (int v = member_head[root]; v != -1; v = member_next[v]) {
            if (!marked[v]) {
                printf("%d %d\n", candidate + 1, v + 1);
                free(parent);
                free(size);
                free(degree);
                free(head);
                free(to);
                free(next);
                free(member_head);
                free(member_next);
                free(marked);
                return 0;
            }
        }
    }

    printf("-1\n");

    free(parent);
    free(size);
    free(degree);
    free(head);
    free(to);
    free(next);
    free(member_head);
    free(member_next);
    free(marked);
    return 0;
}
